import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int from, to, capacity, flow;
        Edge(int from, int to, int capacity, int flow) {
            this.from = from;
            this.to = to;
            this.capacity = capacity;
            this.flow = flow;
        }
    }

    static final int INF = 1 << 29;
    static int MAXN = 500;
    static int n, t, xb, yb;
    static boolean[][] m = new boolean[11][11];
    static int[][] temp = new int[11][11], kaps = new int[11][11];
    static List<Integer>[] g = new ArrayList[MAXN];
    static List<Edge> e = new ArrayList<>();
    static int[] dist = new int[MAXN], ptr = new int[MAXN];

    static {
        for (int i = 0; i < MAXN; i++) {
            g[i] = new ArrayList<>();
        }
    }

    static int findWay(int x1, int y1, int x2, int y2) {
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, x1, y1});
        int[][] dist_map = new int[11][11];
        for (int i = 0; i < n; i++)
            Arrays.fill(dist_map[i], INF);
        while (!q.isEmpty()) {
            int[] v = q.poll();
            int vdist = v[0], x = v[1], y = v[2];
            dist_map[x][y] = vdist;
            if (x > 0 && m[x - 1][y] && dist_map[x - 1][y] > dist_map[x][y] + 1 && ((x - 1 == x2 && y == y2 && temp[x - 1][y] >= dist_map[x][y] + 1) || !(x - 1 == x2 && y == y2) && temp[x - 1][y] > dist_map[x][y] + 1))
                q.offer(new int[]{vdist + 1, x - 1, y});
            if (y > 0 && m[x][y - 1] && dist_map[x][y - 1] > dist_map[x][y] + 1 && ((x == x2 && y - 1 == y2 && temp[x][y - 1] >= dist_map[x][y] + 1) || !(x == x2 && y - 1 == y2) && temp[x][y - 1] > dist_map[x][y] + 1))
                q.offer(new int[]{vdist + 1, x, y - 1});
            if (x < n - 1 && m[x + 1][y] && dist_map[x + 1][y] > dist_map[x][y] + 1 && ((x + 1 == x2 && y == y2 && temp[x + 1][y] >= dist_map[x][y] + 1) || !(x + 1 == x2 && y == y2) && temp[x + 1][y] > dist_map[x][y] + 1))
                q.offer(new int[]{vdist + 1, x + 1, y});
            if (y < n - 1 && m[x][y + 1] && dist_map[x][y + 1] > dist_map[x][y] + 1 && ((x == x2 && y + 1 == y2 && temp[x][y + 1] >= dist_map[x][y] + 1) || !(x == x2 && y + 1 == y2) && temp[x][y + 1] > dist_map[x][y] + 1))
                q.offer(new int[]{vdist + 1, x, y + 1});
        }
        return dist_map[x2][y2];
    }

    static void connectEdge(int u, int v, int cap) {
        e.add(new Edge(u, v, cap, 0));
        g[u].add(e.size() - 1);
        e.add(new Edge(v, u, 0, 0));
        g[v].add(e.size() - 1);
    }

    static boolean isBFS() {
        Arrays.fill(dist, -1);
        Queue<Integer> q = new LinkedList<>();
        q.offer(0);
        dist[0] = 0;
        while (!q.isEmpty()) {
            int v = q.poll();
            for (int id : g[v]) {
                int to = e.get(id).to;
                if (dist[to] == -1 && e.get(id).flow < e.get(id).capacity) {
                    dist[to] = dist[v] + 1;
                    q.offer(to);
                }
            }
        }
        return dist[n * n * 2 + 1] != -1;
    }

    static int pushFlow(int v, int flow) {
        if (v == n * n * 2 + 1 || flow == 0) return flow;
        for (; ptr[v] < g[v].size(); ptr[v]++) {
            int id = g[v].get(ptr[v]);
            int to = e.get(id).to;
            if (dist[to] == dist[v] + 1 && e.get(id).flow < e.get(id).capacity) {
                int pushed = pushFlow(to, Math.min(flow, e.get(id).capacity - e.get(id).flow));
                if (pushed > 0) {
                    e.get(id).flow += pushed;
                    e.get(id ^ 1).flow -= pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int computeMaxFlow() {
        int totalFlow = 0;
        while (isBFS()) {
            Arrays.fill(ptr, 0);
            int pushed;
            while ((pushed = pushFlow(0, INF)) > 0) {
                totalFlow += pushed;
            }
        }
        return totalFlow;
    }

    static int way(int x1, int y1, int x2, int y2) {
        return findWay(x1, y1, x2, y2);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXN; i++) {
            g[i].clear();
        }
        e.clear();

        int k = 1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                temp[i][j] = t;
                if (c == 'Z') {
                    xb = i;
                    yb = j;
                    m[i][j] = false;
                } else if (c == 'Y') {
                    m[i][j] = false;
                } else {
                    m[i][j] = true;
                }
                connectEdge(0, k++, (c == 'Z' || c == 'Y') ? 0 : c - '0');
            }
        }
        int base = n * n + 1;
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            for (int j = 0; j < n; j++) {
                char c = line.charAt(j);
                if (c >= '0' && c <= '9') kaps[i][j] = c - '0';
                connectEdge(base + i * n + j, n * n * 2 + 1, (c == 'Z' || c == 'Y') ? 0 : c - '0');
            }
        }

        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{0, xb, yb});
        while (!q.isEmpty()) {
            int[] v = q.poll();
            int vdist = v[0], x = v[1], y = v[2];
            temp[x][y] = vdist;
            if (x > 0 && vdist + 1 < temp[x - 1][y] && m[x - 1][y]) q.offer(new int[]{vdist + 1, x - 1, y});
            if (y > 0 && vdist + 1 < temp[x][y - 1] && m[x][y - 1]) q.offer(new int[]{vdist + 1, x, y - 1});
            if (x < n - 1 && vdist + 1 < temp[x + 1][y] && m[x + 1][y]) q.offer(new int[]{vdist + 1, x + 1, y});
            if (y < n - 1 && vdist + 1 < temp[x][y + 1] && m[x][y + 1]) q.offer(new int[]{vdist + 1, x, y + 1});
        }

        int total_nodes = n * n;
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                int k1 = total_nodes * (i * n + j);
                for (int z = 0; z < n; z++) {
                    for (int w = 0; w < n; w++) {
                        if (m[i][j] && m[z][w] && way(i, j, z, w) <= t)
                            connectEdge(base + i * n + j, (z * n + w) + total_nodes, INF);
                    }
                }
            }
        }
        System.out.println(computeMaxFlow());
    }
}
